// tables counts every change to a class's table: a class's resolved members are kept until it changes
var tables int

// resolved is what a name is on a class: the nearest class up the chain that declares it decides (a getter, a
// field with its default, or a method) - as a prototype chain does
type resolved struct {
	owner   *Cls
	getter  Member
	field   Default
	isField bool
	method  Member
	static  *Cls
}

func (c *Cls) resolve(n string) *resolved {
	if c.seen != tables || c.cache == nil {
		c.cache = map[string]*resolved{}
		c.seen = tables
	}
	if r, ok := c.cache[n]; ok {
		return r
	}
	r := &resolved{}
	for k := c; k != nil; k = k.Parent {
		g, isGetter := k.getters[n]
		d, isField := k.fields[n]
		m, isMethod := k.methods[n]
		if isGetter || isField || isMethod {
			r.owner = k
			r.getter, r.method = g, m
			if g == nil && isField {
				r.field, r.isField = d, true
			}
			break
		}
		/* a static written in a nearer class's body (`name = "G"` on a theory) is what the name is there */
		if _, isStatic := k.staticDefaults[n]; isStatic {
			r.static = k
			break
		}
	}
	c.cache[n] = r
	return r
}

func owner(c *Cls, n string) *Cls { return c.resolve(n).owner }

// Get reads a member by name: a slot, a getter, a field (its default made on first read), a method (as a program) or a static.
