// theory makes a theory's class once, its rules and theorems read off the class in the order they are written.
func theory(c *Cls) *Obj {
	o := Make(c)
	theories[c.Name] = o
	var chain []*Cls
	for k := c; k != nil; k = k.Parent {
		chain = append([]*Cls{k}, chain...)
	}
	rules, theorems := &List{}, &List{}
	for _, k := range chain {
		for _, n := range k.staticOrder {
			if strings.HasPrefix(n, "rule ") {
				rules.Items = append(rules.Items, Get(c, n))
			} else if strings.HasPrefix(n, "theorem ") {
				theorems.Items = append(theorems.Items, Get(c, n))
			}
		}
	}
	o.slots["rules"] = rules
	o.slots["theorems"] = theorems
	return o
}

