func typeName(x any) string { return fmt.Sprintf("%T", x) }

// --- what the language's operators are here ------------------------------------------------------

// Truthy is what `if` reads: None, false, 0, NaN and "" are false.
func Truthy(x any) bool {
	switch v := x.(type) {
	case nil:
		return false
	case bool:
		return v
	case float64:
		return v != 0 && !math.IsNaN(v)
	case string:
		return v != ""
	}
	return true
}

// Num is a value as a number: None is 0.
func Num(x any) float64 {
	switch v := x.(type) {
	case float64:
		return v
	case nil:
		return 0
	case bool:
		if v {
			return 1
		}
		return 0
	case int:
		return float64(v)
	}
	return math.NaN()
}

func arith(a any) bool {
	switch a.(type) {
	case nil, float64, bool, int:
		return true
	}
	return false
}

// same is `===`: the same number, text or truth value, or the same object.
func same(a, b any) bool {
	switch x := a.(type) {
	case nil:
		return b == nil
	case float64:
		y, ok := b.(float64)
		return ok && x == y
	case bool:
		y, ok := b.(bool)
		return ok && x == y
	case string:
		y, ok := b.(string)
		return ok && x == y
	case *Obj:
		y, ok := b.(*Obj)
		return ok && x == y
	case *List:
		y, ok := b.(*List)
		return ok && x == y
	case *Cls:
		y, ok := b.(*Cls)
		return ok && x == y
	case *Many:
		y, ok := b.(*Many)
		return ok && x == y
	}
	return false
}

// Eq is `==`.
func Eq(a, b any) bool {
	if same(a, b) {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	switch x := a.(type) {
	case *Many:
		for _, i := range x.Items {
			if !Eq(i, b) {
				return false
			}
		}
		return true
	case float64:
		if y, ok := b.(float64); ok {
			return x == y
		}
		return false
	case *List:
		y, ok := b.(*List)
		if !ok || len(x.Items) != len(y.Items) {
			return false
		}
		for i := range x.Items {
			if !Eq(x.Items[i], y.Items[i]) {
				return false
			}
		}
		return true
	case *Obj:
		if x.Cls.findMethod("equals") != nil {
			return Truthy(Call(a, "equals", []any{b}))
		}
	}
	return false
}

func Lt(a, b any) any {
	if arith(a) {
		return Num(a) < Num(b)
	}
	if s, ok := a.(string); ok {
		return s < Str(b)
	}
	return Call(a, "lt", []any{b})
}
func Le(a, b any) any {
	if arith(a) {
		return Num(a) <= Num(b)
	}
	if s, ok := a.(string); ok {
		return s <= Str(b)
	}
	return Call(a, "le", []any{b})
}
func Gt(a, b any) any {
	if arith(a) {
		return Num(a) > Num(b)
	}
	if s, ok := a.(string); ok {
		return s > Str(b)
	}
	return Call(a, "gt", []any{b})
}
func Ge(a, b any) any {
	if arith(a) {
		return Num(a) >= Num(b)
	}
	if s, ok := a.(string); ok {
		return s >= Str(b)
	}
	return Call(a, "ge", []any{b})
}

// wholes are the whole numbers a program counts with, boxed once: a number in an `any` is otherwise made anew
var wholes = func() []any {
	out := make([]any, 4096)
	for i := range out {
		out[i] = float64(i)
	}
	return out
}()

// Box is a number as a value: a small whole number is shared
func Box(x float64) any {
	if x >= 0 && x < 4096 {
		if i := int(x); float64(i) == x && (i != 0 || !math.Signbit(x)) {
			return wholes[i]
		}
	}
	return x
}

func Add(a, b any) any {
	if x, ok := a.(float64); ok {
		if y, ok := b.(float64); ok {
			return Box(x + y)
		}
	}
	if s, ok := a.(string); ok {
		return s + Str(b)
	}
	if arith(a) {
		return Num(a) + Num(b)
	}
	return Call(a, "plus", []any{b})
}
func Sub(a, b any) any {
	if x, ok := a.(float64); ok {
		if y, ok := b.(float64); ok {
			return Box(x - y)
		}
	}
	if arith(a) {
		return Num(a) - Num(b)
	}
	return Call(a, "minus", []any{b})
}
func Mul(a, b any) any {
	if x, ok := a.(float64); ok {
		if y, ok := b.(float64); ok {
			return Box(x * y)
		}
	}
	if arith(a) {
		return Num(a) * Num(b)
	}
	return Call(a, "times", []any{b})
}
func Div(a, b any) any {
	if !arith(a) {
		return Call(a, "over", []any{b})
	}
	x, y := Num(a), Num(b)
	if y == 0 && x == 0 {
		return wholes[0]
	}
	return Box(x / y)
}
func Mod(a, b any) any {
	if arith(a) {
		return Box(math.Mod(Num(a), Num(b)))
	}
	return Call(a, "mod", []any{b})
}
func Neg(a any) any {
	if arith(a) {
		return -Num(a)
	}
	return Get(a, "negated")
}
func Power(a, b any) any {
	if arith(a) {
		return powOf(Num(a), Num(b))
	}
	return Call(a, "pow", []any{b})
}

// OrElse is `a ?? b`.
func OrElse(a any, b func() any) any {
	if a != nil {
		return a
	}
	return b()
}

// Tern is `p ? a : b`.
func Tern(p bool, a func() any, b func() any) any {
	if p {
		return a()
	}
	return b()
}
func Not(a any) bool { return !Truthy(a) }

// Assertion is what a failed `dynamically assert` raises.
func Assertion(says string) error { return fmt.Errorf("assertion failed: %s", says) }

// Str is a value as text, as the bootstrap writes it: whole numbers without a point.
func Str(x any) string {
	switch v := x.(type) {
	case nil:
		return "null"
	case float64:
		return numText(v)
	case string:
		return v
	case bool:
		if v {
			return "true"
		}
		return "false"
	case *List:
		var sb strings.Builder
		for i, e := range v.Items {
			if i > 0 {
				sb.WriteByte(',')
			}
			if e != nil {
				sb.WriteString(Str(e))
			}
		}
		return sb.String()
	case *Obj:
		return v.String()
	case *Cls:
		return v.Name
	case *Many:
		return "Many(" + Str(&List{v.Items}) + ")"
	case Fn:
		return "program"
	}
	return fmt.Sprint(x)
}

// numText writes a number as JavaScript does.
func numText(d float64) string {
	if math.IsNaN(d) {
		return "NaN"
	}
	if math.IsInf(d, 1) {
		return "Infinity"
	}
	if math.IsInf(d, -1) {
		return "-Infinity"
	}
	if d == 0 {
		return "0"
	}
	a := math.Abs(d)
	if a >= 1e-7 && a < 1e21 {
		return strconv.FormatFloat(d, 'f', -1, 64)
	}
	s := strconv.FormatFloat(d, 'e', -1, 64)
	mant, exp, _ := strings.Cut(s, "e")
	sign := exp[0]
	digits := strings.TrimLeft(exp[1:], "0")
	if digits == "" {
		digits = "0"
	}
	return mant + "e" + string(sign) + digits
}

// --- lists and text ------------------------------------------------------------------------------

// Lst is `[a, b]`.
func Lst(xs ...any) *List {
	out := make([]any, len(xs))
	copy(out, xs)
	return &List{out}
}

// Items are the elements of a list, a Many or a text (one each code point) - a snapshot.
func Items(xs any) []any {
	switch v := xs.(type) {
	case *List:
		return v.Items[:len(v.Items):len(v.Items)]
	case *Many:
		return v.Items[:len(v.Items):len(v.Items)]
	case string:
		out := make([]any, 0, len(v))
		for _, r := range v {
			out = append(out, string(r))
		}
		return out
	case nil:
		return nil
	}
	panic(fmt.Errorf("not a list: %s", Str(xs)))
}

func copied(xs any) []any {
	it := Items(xs)
	out := make([]any, len(it))
	copy(out, it)
	return out
}

// Len is `xs.length`.
func Len(xs any) any {
	switch v := xs.(type) {
	case *List:
		return float64(len(v.Items))
	case string:
		return float64(utf16Len(v))
	case *Many:
		return float64(len(v.Items))
	}
	return Get(xs, "length")
}

func utf16Len(s string) int {
	n := 0
	for _, r := range s {
		if r >= 0x10000 {
			n += 2
		} else {
			n++
		}
	}
	return n
}

func index(k any, n int) (int, bool) {
	f := Num(k)
	if math.IsNaN(f) {
		return 0, false
	}
	i := int(f)
	if i < 0 {
		i += n
	}
	return i, i >= 0 && i < n
}

// Elem is `x[k]`: an element of a list (negative from the end), or a member by name.
func Elem(t any, k any) any {
	switch v := t.(type) {
	case *List:
		if i, ok := index(k, len(v.Items)); ok {
			return v.Items[i]
		}
		return nil
	case nil:
		return nil
	case string:
		rs := []rune(v)
		if i, ok := index(k, len(rs)); ok {
			return string(rs[i])
		}
		return nil
	case *Many:
		out := make([]any, len(v.Items))
		for i, x := range v.Items {
			out[i] = Elem(x, k)
		}
		return collapse(out)
	case *Obj, *Cls:
		if s, ok := k.(string); ok {
			return Get(t, s)
		}
		return Get(t, Str(k))
	}
	return nil
}

// SetAt is `x[k] = v`.
func SetAt(t any, k any, v any) any {
	if l, ok := t.(*List); ok {
		i := int(Num(k))
		for len(l.Items) <= i {
			l.Items = append(l.Items, nil)
		}
		l.Items[i] = v
		return v
	}
	if s, ok := k.(string); ok {
		return Set(t, s, v)
	}
	return Set(t, Str(k), v)
}

// Push appends to a list.
func Push(xs any, x any) any {
	l := xs.(*List)
	l.Items = append(l.Items, x)
	return xs
}

// Filt is `xs.filter(f)`.
func Filt(xs any, f any) any {
	if m, ok := xs.(*Many); ok {
		var out []any
		for _, x := range m.Items {
			if Truthy(Invoke(f, []any{x})) {
				out = append(out, x)
			}
		}
		return &Many{out}
	}
	out := []any{}
	for _, x := range Items(xs) {
		if Truthy(Invoke(f, []any{x})) {
			out = append(out, x)
		}
	}
	return &List{out}
}

// Rng is `Array.range(n)`.
func Rng(n any) any {
	k := int(Num(n))
	if k < 0 {
		k = 0
	}
	out := make([]any, k)
	for i := range out {
		out[i] = Box(float64(i))
	}
	return &List{out}
}

// Filled is `Array.filled(n, v)`.
func Filled(n any, v any) any {
	k := int(Num(n))
	if k < 0 {
		k = 0
	}
	out := make([]any, k)
	for i := range out {
		out[i] = v
	}
	return &List{out}
}
func contains(xs any, x any) any {
	if s, ok := xs.(string); ok {
		return strings.Contains(s, Str(x))
	}
	for _, y := range Items(xs) {
		if Eq(y, x) {
			return true
		}
	}
	return false
}
func indexOf(xs any, x any) any {
	if s, ok := xs.(string); ok {
		i := strings.Index(s, Str(x))
		if i < 0 {
			return nil
		}
		return float64(utf8.RuneCountInString(s[:i]))
	}
	for i, y := range Items(xs) {
		if Eq(y, x) {
			return float64(i)
		}
	}
	return nil
}
func first(xs any) any {
	if s, ok := xs.(string); ok {
		for _, r := range s {
			return string(r)
		}
		return nil
	}
	l := Items(xs)
	if len(l) == 0 {
		return nil
	}
	return l[0]
}
func last(xs any) any {
	if s, ok := xs.(string); ok {
		if s == "" {
			return nil
		}
		r, _ := utf8.DecodeLastRuneInString(s)
		return string(r)
	}
	l := Items(xs)
	if len(l) == 0 {
		return nil
	}
	return l[len(l)-1]
}
func join(xs any, sep any) any {
	var sb strings.Builder
	s := Str(sep)
	for i, x := range Items(xs) {
		if i > 0 {
			sb.WriteString(s)
		}
		if x != nil {
			sb.WriteString(Str(x))
		}
	}
	return sb.String()
}

// Quoted is a text in double quotes, escaped as JSON.
func Quoted(x any) any {
	s := Str(x)
	var sb strings.Builder
	sb.WriteByte('"')
	for _, c := range s {
		switch c {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		default:
			if c < 0x20 {
				fmt.Fprintf(&sb, "\\u%04x", c)
			} else {
				sb.WriteRune(c)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}
func most(xs any, key any) any {
	var best any
	at, found := -1, false
	bk := math.Inf(-1)
	for i, x := range Items(xs) {
		k := Num(Invoke(key, []any{x}))
		if !found || k > bk {
			best, at, bk, found = x, i, k, true
		}
	}
	if !found {
		return nil
	}
	return Lst(best, float64(at))
}
func sortedBy(xs any, key any) any {
	l := copied(xs)
	ks := make([]float64, len(l))
	for i, x := range l {
		ks[i] = Num(Invoke(key, []any{x}))
	}
	idx := make([]int, len(l))
	for i := range idx {
		idx[i] = i
	}
	sort.SliceStable(idx, func(p, q int) bool { return ks[idx[p]] < ks[idx[q]] })
	out := make([]any, len(l))
	for i, j := range idx {
		out[i] = l[j]
	}
	return &List{out}
}
func summed(xs any) any {
	s := 0.0
	for _, x := range Items(xs) {
		s += Num(x)
	}
	return s
}

// Fail raises.
func Fail(says any) any { panic(fmt.Errorf("%s", Str(says))) }
func codepoints(s any) any {
	var out []any
	for _, r := range s.(string) {
		out = append(out, float64(r))
	}
	return &List{out}
}

// FromCodepoints is `String(chars: xs)`.
func FromCodepoints(xs any) any {
	var sb strings.Builder
	for _, c := range Items(xs) {
		sb.WriteRune(rune(int(Num(c))))
	}
	return sb.String()
}

// Blank says whether a code point is white space.
func Blank(c any) any { d := Num(c); return d == 32 || d == 9 || d == 10 || d == 13 }

// Number reads a text as a number (NaN where it is none).
func Number(s any) any {
	f, err := strconv.ParseFloat(strings.TrimSpace(Str(s)), 64)
	if err != nil {
		return math.NaN()
	}
	return f
}

// --- the members Ray knows on a list, a text or a number - and any object's own member of that name otherwise ---

func core(x any) bool {
	switch x.(type) {
	case nil, *List, string, float64, bool, *Many:
		return true
	}
	return false
}
func M_push(xs any, a ...any) any {
	if core(xs) {
		return Push(xs, a[0])
	}
	return Call(xs, "push", a)
}
func M_chars(xs any) any {
	if _, ok := xs.(string); ok {
		return codepoints(xs)
	}
	return Get(xs, "chars")
}
func M_pop(xs any) any {
	if core(xs) {
		l := xs.(*List)
		if len(l.Items) == 0 {
			return nil
		}
		v := l.Items[len(l.Items)-1]
		l.Items = l.Items[:len(l.Items)-1]
		return v
	}
	return Get(xs, "pop")
}
func M_map(xs any, a ...any) any {
	if !core(xs) {
		return Call(xs, "map", a)
	}
	it := Items(xs)
	out := make([]any, len(it))
	for i, x := range it {
		out[i] = Invoke(a[0], []any{x})
	}
	return &List{out}
}
func M_for(xs any, a ...any) any {
	if !core(xs) {
		return Call(xs, "for", a)
	}
	for _, x := range Items(xs) {
		Invoke(a[0], []any{x})
	}
	return nil
}
func M_some(xs any, a ...any) any {
	if !core(xs) {
		return Call(xs, "some", a)
	}
	for _, x := range Items(xs) {
		if Truthy(Invoke(a[0], []any{x})) {
			return true
		}
	}
	return false
}
func M_every(xs any, a ...any) any {
	if !core(xs) {
		return Call(xs, "every", a)
	}
	for _, x := range Items(xs) {
		if !Truthy(Invoke(a[0], []any{x})) {
			return false
		}
	}
	return true
}
func M_reduce(xs any, a ...any) any {
	if !core(xs) {
		return Call(xs, "reduce", a)
	}
	acc := a[0]
	for _, x := range Items(xs) {
		acc = Invoke(a[1], []any{acc, x})
	}
	return acc
}
func M_starts_with(xs any, a ...any) any {
	if core(xs) {
		return strings.HasPrefix(xs.(string), Str(a[0]))
	}
	return Call(xs, "starts_with", a)
}
func M_ends_with(xs any, a ...any) any {
	if core(xs) {
		return strings.HasSuffix(xs.(string), Str(a[0]))
	}
	return Call(xs, "ends_with", a)
}
func M_replace(xs any, a ...any) any {
	if core(xs) {
		return strings.ReplaceAll(xs.(string), Str(a[0]), Str(a[1]))
	}
	return Call(xs, "replace", a)
}
func M_split(xs any, a ...any) any {
	if !core(xs) {
		return Call(xs, "split", a)
	}
	s, sep := xs.(string), Str(a[0])
	if sep == "" {
		return &List{Items(s)}
	}
	parts := strings.Split(s, sep)
	out := make([]any, len(parts))
	for i, p := range parts {
		out[i] = p
	}
	return &List{out}
}
func M_trim(xs any) any {
	if core(xs) {
		return strings.TrimSpace(xs.(string))
	}
	return Get(xs, "trim")
}
func M_upper(xs any) any {
	if core(xs) {
		return strings.ToUpper(xs.(string))
	}
	return Get(xs, "upper")
}
func M_lower(xs any) any {
	if core(xs) {
		return strings.ToLower(xs.(string))
	}
	return Get(xs, "lower")
}
func M_lines(xs any) any {
	if core(xs) {
		return M_split(xs, "\n")
	}
	return Get(xs, "lines")
}
func M_contains(xs any, a ...any) any {
	if core(xs) {
		return contains(xs, a[0])
	}
	return Call(xs, "contains", a)
}
func M_index_of(xs any, a ...any) any {
	if core(xs) {
		return indexOf(xs, a[0])
	}
	return Call(xs, "index_of", a)
}
func M_join(xs any, a ...any) any {
	if core(xs) {
		return join(xs, a[0])
	}
	return Call(xs, "join", a)
}
func M_first(xs any) any {
	if core(xs) {
		return first(xs)
	}
	return Get(xs, "first")
}
func M_last(xs any) any {
	if core(xs) {
		return last(xs)
	}
	return Get(xs, "last")
}
func M_empty(xs any) any {
	if core(xs) {
		return Num(Len(xs)) == 0
	}
	return Get(xs, "empty")
}
func M_take(xs any, a ...any) any {
	if !core(xs) {
		return Call(xs, "take", a)
	}
	n := int(Num(a[0]))
	if s, ok := xs.(string); ok {
		rs := []rune(s)
		return string(rs[:clamp(n, len(rs))])
	}
	l := Items(xs)
	out := make([]any, clamp(n, len(l)))
	copy(out, l)
	return &List{out}
}
func M_drop(xs any, a ...any) any {
	if !core(xs) {
		return Call(xs, "drop", a)
	}
	n := int(Num(a[0]))
	if s, ok := xs.(string); ok {
		rs := []rune(s)
		return string(rs[clamp(n, len(rs)):])
	}
	l := Items(xs)
	rest := l[clamp(n, len(l)):]
	out := make([]any, len(rest))
	copy(out, rest)
	return &List{out}
}
func clamp(n, size int) int {
	if n < 0 {
		return 0
	}
	if n > size {
		return size
	}
	return n
}
func M_rest(xs any) any {
	if core(xs) {
		return M_drop(xs, 1.0)
	}
	return Get(xs, "rest")
}
func M_concat(xs any, a ...any) any {
	if !core(xs) {
		return Call(xs, "concat", a)
	}
	if s, ok := xs.(string); ok {
		return s + Str(a[0])
	}
	out := copied(xs)
	out = append(out, Items(a[0])...)
	return &List{out}
}
func M_reverse(xs any) any {
	if !core(xs) {
		return Get(xs, "reverse")
	}
	if s, ok := xs.(string); ok {
		rs := []rune(s)
		for i, j := 0, len(rs)-1; i < j; i, j = i+1, j-1 {
			rs[i], rs[j] = rs[j], rs[i]
		}
		return string(rs)
	}
	out := copied(xs)
	for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
		out[i], out[j] = out[j], out[i]
	}
	return &List{out}
}
func M_sum(xs any) any {
	if core(xs) {
		return summed(xs)
	}
	return Get(xs, "sum")
}
func M_most(xs any, a ...any) any {
	if core(xs) {
		return most(xs, a[0])
	}
	return Call(xs, "most", a)
}
func M_sorted_by(xs any, a ...any) any {
	if core(xs) {
		return sortedBy(xs, a[0])
	}
	return Call(xs, "sorted_by", a)
}
func M_each(xs any) any {
	if core(xs) {
		return &Many{copied(xs)}
	}
	return Get(xs, "each")
}
func mathOf(x any, name string, f func(float64) float64) any {
	if arith(x) {
		return Box(f(Num(x)))
	}
	return Get(x, name)
}
func M_sqrt(x any) any      { return mathOf(x, "sqrt", math.Sqrt) }
func M_floor(x any) any     { return mathOf(x, "floor", math.Floor) }
func M_abs(x any) any       { return mathOf(x, "abs", math.Abs) }
func M_magnitude(x any) any { return mathOf(x, "magnitude", math.Abs) }
func M_cos(x any) any       { return mathOf(x, "cos", cosOf) }
func M_sin(x any) any       { return mathOf(x, "sin", sinOf) }
func M_round(x any) any {
	return mathOf(x, "round", func(v float64) float64 { return math.Floor(v + 0.5) })
}
func M_ln(x any) any  { return mathOf(x, "ln", logOf) }
func M_exp(x any) any { return mathOf(x, "exp", expOf) }
func M_atan2(x any, a ...any) any {
	if arith(x) {
		return atan2Of(Num(x), Num(a[0]))
	}
	return Call(x, "atan2", a)
}
func M_pow(x any, a ...any) any {
	if arith(x) {
		return powOf(Num(x), Num(a[0]))
	}
	return Call(x, "pow", a)
}

// --- the Many: a superposition; members apply elementwise, equal things collapse ----------------------

// Many is a superposition: `x.MOVE` on many rays moves each; `x.vertex` of one point's rays is the point.
type Many struct{ Items []any }

func (m *Many) get(n string) any {
	out := make([]any, len(m.Items))
	for i, x := range m.Items {
		if x != nil {
			out[i] = Get(x, n)
		}
	}
	return collapse(out)
}
func (m *Many) call(n string, a []any) any {
	out := make([]any, len(m.Items))
	for i, x := range m.Items {
		out[i] = Call(x, n, a)
	}
	return collapse(out)
}

// ManyOf is `xs#`.
func ManyOf(xs any) any { return &Many{copied(xs)} }

func collapse(items []any) any {
	if len(items) == 0 {
		return &Many{items}
	}
	f := items[0]
	for _, i := range items {
		if same(i, f) {
			continue
		}
		if _, ok := i.(*List); ok {
			if _, ok := f.(*List); ok && Eq(i, f) {
				continue
			}
		}
		return &Many{items}
	}
	return f
}

// --- the maths of the bootstrap: sin and cos as fdlibm (and JavaScript, and Java) compute them, to the last bit ---
// (Go's own differ in the last place, and a run that feeds a result back in carries that difference on)

const (
	ksS1 = -1.66666666666666324348e-01
	ksS2 = 8.33333333332248946124e-03
	ksS3 = -1.98412698298579493134e-04
	ksS4 = 2.75573137070700676789e-06
	ksS5 = -2.50507602534068634195e-08
	ksS6 = 1.58969099521155010221e-10
	kcC1 = 4.16666666666666019037e-02
	kcC2 = -1.38888888888741095749e-03
	kcC3 = 2.48015872894767294178e-05
	kcC4 = -2.75573143513906633035e-07
	kcC5 = 2.08757232129817482790e-09
	kcC6 = -1.13596475577881948265e-11
)

func highWord(x float64) uint32 { return uint32(math.Float64bits(x) >> 32) }

func kernelSin(x, y float64, iy int) float64 {
	if highWord(x)&0x7fffffff < 0x3e400000 && int(x) == 0 {
		return x
	}
	z := x * x
	v := z * x
	r := ksS2 + z*(ksS3+z*(ksS4+z*(ksS5+z*ksS6)))
	if iy == 0 {
		return x + v*(ksS1+z*r)
	}
	return x - ((z*(0.5*y-v*r) - y) - v*ksS1)
}

func kernelCos(x, y float64) float64 {
	ix := highWord(x) & 0x7fffffff
	if ix < 0x3e400000 && int(x) == 0 {
		return 1
	}
	z := x * x
	r := z * (kcC1 + z*(kcC2+z*(kcC3+z*(kcC4+z*(kcC5+z*kcC6)))))
	if ix < 0x3FD33333 {
		return 1 - (0.5*z - (z*r - x*y))
	}
	qx := 0.28125
	if ix <= 0x3fe90000 {
		qx = math.Float64frombits(uint64(ix-0x00200000) << 32)
	}
	hz := 0.5*z - qx
	a := 1 - qx
	return a - (hz - (z*r - x*y))
}

var npio2hw = func() [32]uint32 {
	var out [32]uint32
	for i := range out {
		out[i] = highWord(float64(i+1)*(math.Pi/2)) & 0x7fffffff
	}
	return out
}()

// remPio2 is x less a whole number n of pi/2, in two parts; ok is false where x is too large for this reduction
func remPio2(x float64) (n int, y0, y1 float64, ok bool) {
	const (
		invpio2 = 6.36619772367581382433e-01
		pio21   = 1.57079632673412561417e+00
		pio21t  = 6.07710050650619224932e-11
		pio22   = 6.07710050630396597660e-11
		pio22t  = 2.02226624879595063154e-21
		pio23   = 2.02226624871116645580e-21
		pio23t  = 8.47842766036889956997e-32
	)
	hx := int32(highWord(x))
	ix := uint32(hx) & 0x7fffffff
	if ix <= 0x3fe921fb {
		return 0, x, 0, true
	}
	if ix < 0x4002d97c {
		if hx > 0 {
			z := x - pio21
			if ix != 0x3ff921fb {
				y0 = z - pio21t
				y1 = (z - y0) - pio21t
			} else {
				z -= pio22
				y0 = z - pio22t
				y1 = (z - y0) - pio22t
			}
			return 1, y0, y1, true
		}
		z := x + pio21
		if ix != 0x3ff921fb {
			y0 = z + pio21t
			y1 = (z - y0) + pio21t
		} else {
			z += pio22
			y0 = z + pio22t
			y1 = (z - y0) + pio22t
		}
		return -1, y0, y1, true
	}
	if ix > 0x413921fb {
		return 0, 0, 0, false
	}
	t := math.Abs(x)
	n = int(t*invpio2 + 0.5)
	fn := float64(n)
	r := t - fn*pio21
	w := fn * pio21t
	if n < 32 && ix != npio2hw[n-1] {
		y0 = r - w
	} else {
		j := ix >> 20
		y0 = r - w
		i := int(j) - int((highWord(y0)>>20)&0x7ff)
		if i > 16 {
			t = r
			w = fn * pio22
			r = t - w
			w = fn*pio22t - ((t - r) - w)
			y0 = r - w
			i = int(j) - int((highWord(y0)>>20)&0x7ff)
			if i > 49 {
				t = r
				w = fn * pio23
				r = t - w
				w = fn*pio23t - ((t - r) - w)
				y0 = r - w
			}
		}
	}
	y1 = (r - y0) - w
	if hx < 0 {
		return -n, -y0, -y1, true
	}
	return n, y0, y1, true
}

func sinOf(x float64) float64 {
	if math.IsNaN(x) || math.IsInf(x, 0) {
		return math.NaN()
	}
	n, y0, y1, ok := remPio2(x)
	if !ok {
		return math.Sin(x)
	}
	if highWord(x)&0x7fffffff <= 0x3fe921fb {
		return kernelSin(x, 0, 0)
	}
	switch n & 3 {
	case 0:
		return kernelSin(y0, y1, 1)
	case 1:
		return kernelCos(y0, y1)
	case 2:
		return -kernelSin(y0, y1, 1)
	}
	return -kernelCos(y0, y1)
}

func cosOf(x float64) float64 {
	if math.IsNaN(x) || math.IsInf(x, 0) {
		return math.NaN()
	}
	n, y0, y1, ok := remPio2(x)
	if !ok {
		return math.Cos(x)
	}
	if highWord(x)&0x7fffffff <= 0x3fe921fb {
		return kernelCos(x, 0)
	}
	switch n & 3 {
	case 0:
		return kernelCos(y0, y1)
	case 1:
		return -kernelSin(y0, y1, 1)
	case 2:
		return -kernelCos(y0, y1)
	}
	return kernelSin(y0, y1, 1)
}

// atan, atan2, exp and log, as fdlibm computes them

var atanHi = [4]float64{4.63647609000806093515e-01, 7.85398163397448278999e-01, 9.82793723247329054082e-01, 1.57079632679489655800e+00}
var atanLo = [4]float64{2.26987774529616870924e-17, 3.06161699786838301793e-17, 1.39033110312309984516e-17, 6.12323399573676603587e-17}
var atanT = [11]float64{3.33333333333329318027e-01, -1.99999999998764832476e-01, 1.42857142725034663711e-01, -1.11111104054623557880e-01,
	9.09088713343650656196e-02, -7.69187620504482999495e-02, 6.66107313738753120669e-02, -5.83357013379057348645e-02,
	4.97687799461593236017e-02, -3.65315727442169155270e-02, 1.62858201153657823623e-02}

func atanOf(x float64) float64 {
	hx := int32(highWord(x))
	ix := uint32(hx) & 0x7fffffff
	if ix >= 0x44100000 {
		if math.IsNaN(x) {
			return x
		}
		if hx > 0 {
			return atanHi[3] + atanLo[3]
		}
		return -atanHi[3] - atanLo[3]
	}
	id := -1
	if ix < 0x3fdc0000 {
		if ix < 0x3e200000 {
			return x
		}
	} else {
		x = math.Abs(x)
		if ix < 0x3ff30000 {
			if ix < 0x3fe60000 {
				id = 0
				x = (2.0*x - 1.0) / (2.0 + x)
			} else {
				id = 1
				x = (x - 1.0) / (x + 1.0)
			}
		} else if ix < 0x40038000 {
			id = 2
			x = (x - 1.5) / (1.0 + 1.5*x)
		} else {
			id = 3
			x = -1.0 / x
		}
	}
	z := x * x
	w := z * z
	s1 := z * (atanT[0] + w*(atanT[2]+w*(atanT[4]+w*(atanT[6]+w*(atanT[8]+w*atanT[10])))))
	s2 := w * (atanT[1] + w*(atanT[3]+w*(atanT[5]+w*(atanT[7]+w*atanT[9]))))
	if id < 0 {
		return x - x*(s1+s2)
	}
	z = atanHi[id] - ((x*(s1+s2) - atanLo[id]) - x)
	if hx < 0 {
		return -z
	}
	return z
}

func atan2Of(y, x float64) float64 {
	const (
		tiny = 1.0e-300
		piO4 = 7.8539816339744827900e-01
		piO2 = 1.5707963267948965580e+00
		pi   = 3.1415926535897931160e+00
		piLo = 1.2246467991473531772e-16
	)
	if math.IsNaN(x) || math.IsNaN(y) {
		return x + y
	}
	bx, by := math.Float64bits(x), math.Float64bits(y)
	hx, hy := int32(bx>>32), int32(by>>32)
	lx, ly := uint32(bx), uint32(by)
	ix, iy := hx&0x7fffffff, hy&0x7fffffff
	if bx == 0x3ff0000000000000 {
		return atanOf(y)
	}
	m := int((hy>>31)&1) | int((hx>>30)&2)
	if uint32(iy)|ly == 0 {
		switch m {
		case 0, 1:
			return y
		case 2:
			return pi + tiny
		}
		return -pi - tiny
	}
	if uint32(ix)|lx == 0 {
		if hy < 0 {
			return -piO2 - tiny
		}
		return piO2 + tiny
	}
	if ix == 0x7ff00000 {
		if iy == 0x7ff00000 {
			switch m {
			case 0:
				return piO4 + tiny
			case 1:
				return -piO4 - tiny
			case 2:
				return 3.0*piO4 + tiny
			}
			return -3.0*piO4 - tiny
		}
		switch m {
		case 0:
			return 0
		case 1:
			return math.Copysign(0, -1)
		case 2:
			return pi + tiny
		}
		return -pi - tiny
	}
	if iy == 0x7ff00000 {
		if hy < 0 {
			return -piO2 - tiny
		}
		return piO2 + tiny
	}
	k := (iy - ix) >> 20
	var z float64
	if k > 60 {
		z = piO2 + 0.5*piLo
		m &= 1
	} else if hx < 0 && k < -60 {
		z = 0
	} else {
		z = atanOf(math.Abs(y / x))
	}
	switch m {
	case 0:
		return z
	case 1:
		return -z
	case 2:
		return pi - (z - piLo)
	}
	return (z - piLo) - pi
}

func expOf(x float64) float64 {
	const (
		oThreshold = 7.09782712893383973096e+02
		uThreshold = -7.45133219101941108420e+02
		invln2     = 1.44269504088896338700e+00
		ln2Hi      = 6.93147180369123816490e-01
		ln2Lo      = 1.90821492927058770002e-10
		P1         = 1.66666666666666019037e-01
		P2         = -2.77777777770155933842e-03
		P3         = 6.61375632143793436117e-05
		P4         = -1.65339022054652515390e-06
		P5         = 4.13813679705723846039e-08
	)
	halF := [2]float64{0.5, -0.5}
	b := math.Float64bits(x)
	hx := uint32(b >> 32)
	xsb := int(hx>>31) & 1
	hx &= 0x7fffffff
	if hx >= 0x40862E42 {
		if hx >= 0x7ff00000 {
			if math.IsNaN(x) {
				return x
			}
			if xsb == 0 {
				return x
			}
			return 0
		}
		if x > oThreshold {
			return math.Inf(1)
		}
		if x < uThreshold {
			return 0
		}
	}
	var hi, lo float64
	k := 0
	if hx > 0x3fd62e42 {
		if hx < 0x3FF0A2B2 {
			if xsb == 0 {
				hi, lo, k = x-ln2Hi, ln2Lo, 1
			} else {
				hi, lo, k = x+ln2Hi, -ln2Lo, -1
			}
		} else {
			k = int(invln2*x + halF[xsb])
			t := float64(k)
			hi = x - t*ln2Hi
			lo = t * ln2Lo
		}
		x = hi - lo
	} else if hx < 0x3e300000 {
		return 1 + x
	}
	t := x * x
	c := x - t*(P1+t*(P2+t*(P3+t*(P4+t*P5))))
	if k == 0 {
		return 1 - ((x*c)/(c-2.0) - x)
	}
	y := 1 - ((lo - (x*c)/(2.0-c)) - hi)
	if k >= -1021 {
		if k == 1024 {
			return y * 2.0 * math.Float64frombits(0x7fe0000000000000)
		}
		return y * math.Float64frombits(uint64(0x3ff+k)<<52)
	}
	return y * math.Float64frombits(uint64(0x3ff+k+1000)<<52) * 9.33263618503218878990e-302
}

func logOf(x float64) float64 {
	const (
		ln2Hi = 6.93147180369123816490e-01
		ln2Lo = 1.90821492927058770002e-10
		two54 = 1.80143985094819840000e+16
		Lg1   = 6.666666666666735130e-01
		Lg2   = 3.999999999940941908e-01
		Lg3   = 2.857142874366239149e-01
		Lg4   = 2.222219843214978396e-01
		Lg5   = 1.818357216161805012e-01
		Lg6   = 1.531383769920937332e-01
		Lg7   = 1.479819860511658591e-01
	)
	b := math.Float64bits(x)
	hx := int32(b >> 32)
	lx := uint32(b)
	k := int32(0)
	if hx < 0x00100000 {
		if (uint32(hx)&0x7fffffff)|lx == 0 {
			return math.Inf(-1)
		}
		if hx < 0 {
			return math.NaN()
		}
		k -= 54
		x *= two54
		hx = int32(highWord(x))
	}
	if hx >= 0x7ff00000 {
		return x + x
	}
	k += (hx >> 20) - 1023
	hx &= 0x000fffff
	i := (hx + 0x95f64) & 0x100000
	x = math.Float64frombits(uint64(uint32(hx|(i^0x3ff00000)))<<32 | (math.Float64bits(x) & 0xffffffff))
	k += i >> 20
	f := x - 1.0
	dk := float64(k)
	if (0x000fffff & (2 + hx)) < 3 {
		if f == 0 {
			if k == 0 {
				return 0
			}
			return dk*ln2Hi + dk*ln2Lo
		}
		R := f * f * (0.5 - 0.33333333333333333*f)
		if k == 0 {
			return f - R
		}
		return dk*ln2Hi - ((R - dk*ln2Lo) - f)
	}
	s := f / (2.0 + f)
	z := s * s
	i = hx - 0x6147a
	w := z * z
	j := 0x6b851 - hx
	t1 := w * (Lg2 + w*(Lg4+w*Lg6))
	t2 := z * (Lg1 + w*(Lg3+w*(Lg5+w*Lg7)))
	i |= j
	R := t2 + t1
	if i > 0 {
		hfsq := 0.5 * f * f
		if k == 0 {
			return f - (hfsq - s*(hfsq+R))
		}
		return dk*ln2Hi - ((hfsq - (s*(hfsq+R) + dk*ln2Lo)) - f)
	}
	if k == 0 {
		return f - s*(f-R)
	}
	return dk*ln2Hi - ((s*(f-R) - dk*ln2Lo) - f)
}

func lowCleared(x float64) float64 { return math.Float64frombits(math.Float64bits(x) &^ 0xffffffff) }
func withHigh(x float64, hi int32) float64 {
	return math.Float64frombits(uint64(uint32(hi))<<32 | (math.Float64bits(x) & 0xffffffff))
}

// powOf is x to the y, as fdlibm computes it
func powOf(x, y float64) float64 {
	const (
		two53  = 9007199254740992.0
		L1     = 5.99999999999994648725e-01
		L2     = 4.28571428578550184252e-01
		L3     = 3.33333329818377432918e-01
		L4     = 2.72728123808534006489e-01
		L5     = 2.30660745775561754067e-01
		L6     = 2.06975017800338417784e-01
		P1     = 1.66666666666666019037e-01
		P2     = -2.77777777770155933842e-03
		P3     = 6.61375632143793436117e-05
		P4     = -1.65339022054652515390e-06
		P5     = 4.13813679705723846039e-08
		lg2    = 6.93147180559945286227e-01
		lg2H   = 6.93147182464599609375e-01
		lg2L   = -1.90465429995776804525e-09
		ovt    = 8.0085662595372944372e-17
		cp     = 9.61796693925975554329e-01
		cpH    = 9.61796700954437255859e-01
		cpL    = -7.02846165095275826516e-09
		ivln2  = 1.44269504088896338700e+00
		ivln2H = 1.44269502162933349609e+00
		ivln2L = 1.92596299112661746887e-08
	)
	huge, tiny := 1.0e300, 1.0e-300
	bp := [2]float64{1.0, 1.5}
	dpH := [2]float64{0.0, 5.84962487220764160156e-01}
	dpL := [2]float64{0.0, 1.35003920212974897128e-08}
	bx, by := math.Float64bits(x), math.Float64bits(y)
	hx, hy := int32(bx>>32), int32(by>>32)
	lx, ly := uint32(bx), uint32(by)
	ix, iy := hx&0x7fffffff, hy&0x7fffffff
	if uint32(iy)|ly == 0 {
		return 1
	}
	if ix > 0x7ff00000 || (ix == 0x7ff00000 && lx != 0) || iy > 0x7ff00000 || (iy == 0x7ff00000 && ly != 0) {
		return math.NaN()
	}
	yisint := int32(0)
	if hx < 0 {
		if iy >= 0x43400000 {
			yisint = 2
		} else if iy >= 0x3ff00000 {
			k := (iy >> 20) - 0x3ff
			if k > 20 {
				j := ly >> uint(52-k)
				if j<<uint(52-k) == ly {
					yisint = 2 - int32(j&1)
				}
			} else if ly == 0 {
				j := iy >> uint(20-k)
				if j<<uint(20-k) == iy {
					yisint = 2 - (j & 1)
				}
			}
		}
	}
	if ly == 0 {
		if iy == 0x7ff00000 {
			if (ix-0x3ff00000)|int32(lx) == 0 {
				return math.NaN()
			} else if ix >= 0x3ff00000 {
				if hy >= 0 {
					return y
				}
				return 0
			}
			if hy < 0 {
				return -y
			}
			return 0
		}
		if iy == 0x3ff00000 {
			if hy < 0 {
				return 1 / x
			}
			return x
		}
		if hy == 0x40000000 {
			return x * x
		}
		if hy == 0x3fe00000 && hx >= 0 {
			return math.Sqrt(x)
		}
	}
	ax := math.Abs(x)
	if lx == 0 && (ix == 0x7ff00000 || ix == 0 || ix == 0x3ff00000) {
		z := ax
		if hy < 0 {
			z = 1 / z
		}
		if hx < 0 {
			if (ix-0x3ff00000)|yisint == 0 {
				z = math.NaN()
			} else if yisint == 1 {
				z = -z
			}
		}
		return z
	}
	n := int32(uint32(hx)>>31) - 1
	if n|yisint == 0 {
		return math.NaN()
	}
	s := 1.0
	if n|(yisint-1) == 0 {
		s = -1.0
	}
	var t1, t2 float64
	if iy > 0x41e00000 {
		if iy > 0x43f00000 {
			if ix <= 0x3fefffff {
				if hy < 0 {
					return huge * huge
				}
				return tiny * tiny
			}
			if ix >= 0x3ff00000 {
				if hy > 0 {
					return huge * huge
				}
				return tiny * tiny
			}
		}
		if ix < 0x3fefffff {
			if hy < 0 {
				return s * huge * huge
			}
			return s * tiny * tiny
		}
		if ix > 0x3ff00000 {
			if hy > 0 {
				return s * huge * huge
			}
			return s * tiny * tiny
		}
		t := ax - 1
		w := (t * t) * (0.5 - t*(0.3333333333333333333333-t*0.25))
		u := ivln2H * t
		v := t*ivln2L - w*ivln2
		t1 = lowCleared(u + v)
		t2 = v - (t1 - u)
	} else {
		n = 0
		if ix < 0x00100000 {
			ax *= two53
			n -= 53
			ix = int32(highWord(ax))
		}
		n += (ix >> 20) - 0x3ff
		j := ix & 0x000fffff
		ix = j | 0x3ff00000
		k := 0
		if j <= 0x3988E {
			k = 0
		} else if j < 0xBB67A {
			k = 1
		} else {
			k = 0
			n++
			ix -= 0x00100000
		}
		ax = withHigh(ax, ix)
		u := ax - bp[k]
		v := 1 / (ax + bp[k])
		ss := u * v
		sH := lowCleared(ss)
		tH := math.Float64frombits(uint64(uint32(((ix>>1)|0x20000000)+0x00080000+int32(k<<18))) << 32)
		tL := ax - (tH - bp[k])
		sL := v * ((u - sH*tH) - sH*tL)
		s2 := ss * ss
		r := s2 * s2 * (L1 + s2*(L2+s2*(L3+s2*(L4+s2*(L5+s2*L6)))))
		r += sL * (sH + ss)
		s2 = sH * sH
		tH = lowCleared(3.0 + s2 + r)
		tL = r - ((tH - 3.0) - s2)
		u = sH * tH
		v = sL*tH + tL*ss
		pH := lowCleared(u + v)
		pL := v - (pH - u)
		zH := cpH * pH
		zL := cpL*pH + pL*cp + dpL[k]
		t := float64(n)
		t1 = lowCleared(((zH + zL) + dpH[k]) + t)
		t2 = zL - (((t1 - t) - dpH[k]) - zH)
	}
	y1 := lowCleared(y)
	pL := (y-y1)*t1 + y*t2
	pH := y1 * t1
	z := pL + pH
	bz := math.Float64bits(z)
	j := int32(bz >> 32)
	i := int32(uint32(bz))
	if j >= 0x40900000 {
		if (j-0x40900000)|i != 0 {
			return s * huge * huge
		}
		if pL+ovt > z-pH {
			return s * huge * huge
		}
	} else if j&0x7fffffff >= 0x4090cc00 {
		if (j-0x4090cc00)|i != 0 {
			return s * tiny * tiny
		}
		if pL <= z-pH {
			return s * tiny * tiny
		}
	}
	i = j & 0x7fffffff
	k := (i >> 20) - 0x3ff
	n = 0
	if i > 0x3fe00000 {
		n = j + (0x00100000 >> uint(k+1))
		k = ((n & 0x7fffffff) >> 20) - 0x3ff
		t := math.Float64frombits(uint64(uint32(n&^(0x000fffff>>uint(k)))) << 32)
		n = ((n & 0x000fffff) | 0x00100000) >> uint(20-k)
		if j < 0 {
			n = -n
		}
		pH -= t
	}
	t := lowCleared(pL + pH)
	u := t * lg2H
	v := (pL-(t-pH))*lg2 + t*lg2L
	z = u + v
	w := v - (z - u)
	t = z * z
	t1 = z - t*(P1+t*(P2+t*(P3+t*(P4+t*P5))))
	r := (z*t1)/(t1-2) - (w + z*w)
	z = 1 - (r - z)
	j = int32(highWord(z))
	j += n << 20
	if j>>20 <= 0 {
		z = math.Ldexp(z, int(n))
	} else {
		z = withHigh(z, j)
	}
	return s * z
}
